"""Network and API connectivity diagnostic checks."""

from .models import CheckResult, CheckStatus


def run_checks(verbose: bool = False) -> list[CheckResult]:  # noqa: ARG001
    """Run network and API connectivity diagnostic checks."""
    results = []
    results.append(_check_api_reachable())
    results.append(_check_dns_resolution())
    return results


def _get_configured_url() -> str:
    """Get the configured API URL (same resolution as QbraidSessionV1)."""
    import os

    from qbraid_core.config import DEFAULT_CONFIG_SECTION, DEFAULT_ENDPOINT_URL, load_config

    url = os.environ.get("QBRAID_API_URL")
    if not url:
        try:
            config = load_config()
            if config.has_option(DEFAULT_CONFIG_SECTION, "url"):
                url = config.get(DEFAULT_CONFIG_SECTION, "url")
        except Exception:
            pass
    return (url or DEFAULT_ENDPOINT_URL).rstrip("/")


def _check_api_reachable() -> CheckResult:
    """Check if the qBraid API is reachable."""
    try:
        import requests

        url = _get_configured_url()

        # Try a lightweight request (HEAD or GET /health if available)
        response = requests.get(f"{url}/health", timeout=10)

        if response.status_code < 500:
            return CheckResult(
                name="network.api_reachable",
                category="network",
                status=CheckStatus.PASS,
                message=f"qBraid API is reachable at {url} (HTTP {response.status_code})",
            )
        return CheckResult(
            name="network.api_reachable",
            category="network",
            status=CheckStatus.WARN,
            message=f"qBraid API returned server error: HTTP {response.status_code}",
            details={"url": url, "status_code": response.status_code},
        )
    except requests.ConnectionError:
        return CheckResult(
            name="network.api_reachable",
            category="network",
            status=CheckStatus.FAIL,
            message="Cannot connect to qBraid API.",
            fix_hint=(
                "Check your internet connection." " If behind a proxy, set HTTP_PROXY/HTTPS_PROXY."
            ),
        )
    except requests.Timeout:
        return CheckResult(
            name="network.api_reachable",
            category="network",
            status=CheckStatus.FAIL,
            message="Connection to qBraid API timed out (10s).",
            fix_hint="Check your network connection or try again later.",
        )
    except Exception as exc:
        return CheckResult(
            name="network.api_reachable",
            category="network",
            status=CheckStatus.ERROR,
            message=f"Network check error: {exc}",
        )


def _check_dns_resolution() -> CheckResult:
    """Check DNS resolution for qBraid API host."""
    try:
        import socket
        from urllib.parse import urlparse

        url = _get_configured_url()
        host = urlparse(url).hostname

        if not host:
            return CheckResult(
                name="network.dns_resolution",
                category="network",
                status=CheckStatus.FAIL,
                message=f"Could not extract hostname from URL: {url}",
            )

        addr = socket.gethostbyname(host)
        return CheckResult(
            name="network.dns_resolution",
            category="network",
            status=CheckStatus.PASS,
            message=f"DNS resolution OK: {host} -> {addr}",
        )
    except socket.gaierror as exc:
        return CheckResult(
            name="network.dns_resolution",
            category="network",
            status=CheckStatus.FAIL,
            message=f"DNS resolution failed: {exc}",
            fix_hint="Check your DNS settings or internet connection.",
        )
    except Exception as exc:
        return CheckResult(
            name="network.dns_resolution",
            category="network",
            status=CheckStatus.ERROR,
            message=f"DNS check error: {exc}",
        )
